import { GoogleGenAI } from "@google/genai";
import { ERDONA_PROFILE, PROJECTS, SKILLS } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const systemInstruction = `
You are the digital twin assistant of Erdona Kadriolli. 
Erdona is a ${ERDONA_PROFILE.title}. 
Your goal is to represent her professionally, warmly, and helpfully to visitors of her portfolio.

Details about Erdona:
- Name: ${ERDONA_PROFILE.name}
- Bio: ${ERDONA_PROFILE.bio}
- Projects: ${PROJECTS.map(p => `${p.title}: ${p.description}`).join(', ')}
- Skills: ${SKILLS.map(s => s.name).join(', ')}
- Contact: ${ERDONA_PROFILE.email}

Instructions:
1. Speak as Erdona's representative.
2. Keep responses concise but engaging.
3. If asked about her experience, mention her skills and projects.
4. If someone wants to hire her, direct them to the contact section or her email.
5. Use a friendly, modern tone.
`;

export const getGeminiChatResponse = async (history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: history.map(h => ({ role: h.role, parts: h.parts })),
      config: {
        systemInstruction,
        temperature: 0.7,
        topP: 0.9,
      }
    });

    return response.text || "I'm sorry, I'm having a bit of trouble connecting to Erdona's memory right now.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I encountered an error. Please try again or reach out to Erdona directly!";
  }
};

