import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Projects from './components/Projects';
import Contact from './components/Contact';
import Footer from './components/Footer';
import AIChat from './components/AIChat';
import AdminPanel from './components/AdminPanel';
import Intro from './components/Intro';
import { PROJECTS as INITIAL_PROJECTS } from './constants';
import { Project } from './types';

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('erdona_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  useEffect(() => {
    localStorage.setItem('erdona_projects', JSON.stringify(projects));
  }, [projects]);

  const addProject = (p: Project) => {
    setProjects([p, ...projects]);
  };

  const deleteProject = (id: string) => {
    setProjects(projects.filter(p => p.id !== id));
  };

  if (showIntro) {
    return <Intro onComplete={() => setShowIntro(false)} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 selection:bg-blue-100 selection:text-blue-900 transition-colors duration-500">
      <Navbar />
      <main>
        <Hero />
        <Projects projects={projects} />
        <About />
        <Contact />
      </main>
      <Footer onAdminClick={() => setIsAdminOpen(true)} />
      <AIChat />

      {isAdminOpen && (
        <AdminPanel 
          projects={projects} 
          onClose={() => setIsAdminOpen(false)} 
          onAdd={addProject} 
          onDelete={deleteProject}
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
