      clearTimeout(endTimer);
    };
  }, [onComplete]);

  return (
    <div className={`fixed inset-0 z-[1000] flex items-center justify-center bg-white transition-all duration-700 ${exit ? 'opacity-0 scale-110 pointer-events-none' : 'opacity-100'}`}>
      <div className="text-center">
