interface AdminPanelProps {
  projects: Project[];
  onClose: () => void;
  onAdd: (p: Project) => void;
  onDelete: (id: string) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ projects, onClose, onAdd, onDelete }) => {
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [tags, setTags] = useState('');
  const [img, setImg] = useState('https://picsum.photos/seed/' + Math.random() + '/800/600');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !desc) return;

    const newProj: Project = {
      id: Date.now().toString(),
      title,
      description: desc,
      tags: tags.split(',').map(t => t.trim()),
      image: img,
      link: '#'
    };

    onAdd(newProj);
    setTitle('');
    setDesc('');
    setTags('');
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-6 border-b flex justify-between items-center bg-blue-50/50">
          <h2 className="text-xl font-bold text-slate-900">Project Manager</h2>
