              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">
          <form onSubmit={handleSubmit} className="space-y-4 bg-slate-50 p-6 rounded-2xl border border-blue-100">
            <h3 className="font-bold text-blue-600 uppercase text-xs tracking-widest">Add New Project</h3>
            <input 
              className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all" 
              placeholder="Project Title" 
              value={title}
              onChange={e => setTitle(e.target.value)}
            />
            <textarea 
              className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all" 
              placeholder="Description"
              rows={3}
              value={desc}
              onChange={e => setDesc(e.target.value)}
            />
            <input 
              className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl focus:outline-none focus:border-blue-500 transition-all" 
              placeholder="Tags (comma separated)" 
              value={tags}
              onChange={e => setTags(e.target.value)}
            />
            <button className="w-full py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20">
              Publish Project
            </button>
          </form>

          <div className="space-y-4">
